import java.util.List;

public class OrderService {
    @FunctionalInterface
    interface OrderValidator {
        boolean isValid(Order order);

        default OrderValidator and(OrderValidator other) {
            return order -> isValid(order) && other.isValid(order);
        }
    }

    record Order(long id, double amount, String status) {}

    List<Order> filterOrders(List<Order> orders, OrderValidator validator) {
        return orders.stream().filter(validator::isValid).toList();
    }

    public static void main(String[] args) {
        var service = new OrderService();
        var orders = List.of(new Order(1L, 100.0, "PENDING"));
        var valid = service.filterOrders(orders, order -> order.amount() > 50);
        System.out.println(valid);
    }
}
