import java.util.List;
import java.util.function.Predicate;

record Order(long id, double amount, String status, String customerType) {}

public class OrderFilter {
    private static final Predicate<Order> HIGH_VALUE =
        order -> order.amount() > 1_000;
    private static final Predicate<Order> PENDING =
        order -> "PENDING".equals(order.status());
    private static final Predicate<Order> PREMIUM =
        order -> "PREMIUM".equals(order.customerType());

    public List<Order> filterOrders(List<Order> orders) {
        Predicate<Order> priority = HIGH_VALUE.and(PENDING).or(PREMIUM);
        return orders.stream().filter(priority).toList();
    }

    public static void main(String[] args) {
        var filter = new OrderFilter();
        var orders = List.of(
            new Order(1L, 1_500.0, "PENDING", "REGULAR"),
            new Order(2L, 500.0, "COMPLETE", "PREMIUM")
        );
        System.out.println(filter.filterOrders(orders));
    }
}
