import java.util.function.Function;

public class AndThenVsCompose {
    public static void main(String[] args) {
        Function<Integer, Integer> times2 = x -> x * 2;
        Function<Integer, Integer> plus3  = x -> x + 3;

        // andThen: times2 first, then plus3 -> (5*2)+3
        System.out.println(times2.andThen(plus3).apply(5)); // 13

        // compose: plus3 first, then times2 -> (5+3)*2
        System.out.println(times2.compose(plus3).apply(5)); // 16
    }
}
