public class RegistrationDemo {
    static final class ValidationResult {
        private final boolean valid;
        private final String message;

        ValidationResult(boolean valid, String message) {
            this.valid = valid;
            this.message = message;
        }

        boolean isValid() { return valid; }
        String getMessage() { return message; }
    }

    static final class ValidationException extends Exception {
        ValidationException(String message) { super(message); }
    }

    static final class UserRegistration {
        private final String email;
        private final int age;

        UserRegistration(String email, int age) {
            this.email = email;
            this.age = age;
        }
    }

    @FunctionalInterface
    interface DataValidator<T> {
        ValidationResult validate(T data) throws ValidationException;

        default DataValidator<T> and(DataValidator<T> other) {
            return data -> {
                ValidationResult first = validate(data);
                return first.isValid() ? other.validate(data) : first;
            };
        }
    }

    public static void main(String[] args) throws ValidationException {
        DataValidator<UserRegistration> email = reg ->
            new ValidationResult(reg.email.contains("@"), "Email must contain @");
        DataValidator<UserRegistration> adult = reg ->
            new ValidationResult(reg.age >= 18, "User must be 18 or older");

        ValidationResult result = email.and(adult)
            .validate(new UserRegistration("asha@example.com", 21));
        System.out.println(result.isValid() ? "Valid" : result.getMessage());
    }
}
